478,1813,'_sec_2_button','field_5de6e58c86706'),(59479,1813,'sec_3_button','<a class=\"btn btn-home\" href=\"/hyveclean/the-project/\">Detailed project description</a> <a class=\"btn btn-home\" href=\"#location\">Location map</a>'),(59480,1813,'_sec_3_button','field_5de6e5a243c03'),(59481,1813,'page_col_image_4','455'),(59482,1813,'_page_col_image_4','field_5de70801090ce'),(59483,1813,'sec_4_title','Location'),(59484,1813,'_sec_4_title','field_5de7082a12a81'),(59485,1813,'sec_4_text','The project will be located in Central NSW about 5km south-west of the small rural township of Coolah. About 120 wind turbines are being proposed across two clusters at Mount Hope and Black Stump.'),(59486,1813,'_sec_4_text','field_5de7084812a82'),(59487,1813,'sec_4_button','<a class=\"btn btn-home\" href=\"/hyveclean/about/\">Detailed location information</a>'),(59488,1813,'_sec_4_button','field_5de7085e12a83'),(59489,1813,'news_title','Project updates'),(59490,1813,'_news_title','field_5de78da3aabb9'),(59491,1813,'sec_2_text_copy',''),(59492,1813,'_sec_2_text_copy','field_5de78dc89e613'),(59493,1813,'timeline-title','Timeline'),(59494,1813,'_timeline-title','field_5de78df29e615'),(59495,1813,'timeline_title','Timeline'),(59496,1813,'_timeline_title','field_5de78df29e615'),(59497,1813,'contact_title','Contact us'),(59498,1813,'_contact_title','field_5de7981e06057'),(59499,1813,'contact_intro','Contact text...'),(59500,1813,'_contact_intro','field_5de7983506058'),(59501,1813,'news_button','<a class=\"btn btn-home btn-news\" href=\"/updates/\">See all updates</a>'),(59502,1813,'_news_button','field_5de8329896e02'),(59503,1813,'timeline_intro','Introduction of timeline detail...'),(59504,1813,'_timeline_intro','field_5de98f5fb1781'),(59505,1813,'timeline_pic','477'),(59506,1813,'_timeline_pic','field_5de98f72b1782'),(59507,1813,'timeline_button','<a class=\"btn btn-home btn-news\" href=\"/about/\">Detailed timeline</a>'),(59508,1813,'_timeline_button','field_5de99363677f8'),(59509,1813,'