ent','field_640e8b307a958'),(71698,1864,'problem_icons_0_prob_icon','1699'),(71699,1864,'_problem_icons_0_prob_icon','field_640fa0291d519'),(71700,1864,'problem_icons_0_prob_concerned_stat','70% highly concerned'),(71701,1864,'_problem_icons_0_prob_concerned_stat','field_640fa0dd81d95'),(71702,1864,'problem_icons_0_prob_concerded_text','are highly concerned'),(71703,1864,'_problem_icons_0_prob_concerded_text','field_640fa10181d96'),(71704,1864,'problem_icons_0_prob_issue_text',''),(71705,1864,'_problem_icons_0_prob_issue_text','field_640fa11a81d97'),(71706,1864,'problem_icons','4'),(71707,1864,'_problem_icons','field_640fa0191d518'),(71708,1864,'ceh_content_left',''),(71709,1864,'_ceh_content_left','field_640e97e8f1c8c'),(71710,1864,'ceh_content_right',''),(71711,1864,'_ceh_content_right','field_640e97fdf1c8d'),(71712,1864,'pc_content_left',''),(71713,1864,'_pc_content_left','field_640e983bf1c8f'),(71714,1864,'pc_content_right',''),(71715,1864,'_pc_content_right','field_640e984df1c90'),(71716,1864,'problem_icons_1_prob_icon','1699'),(71717,1864,'_problem_icons_1_prob_icon','field_640fa0291d519'),(71718,1864,'problem_icons_1_prob_concerned_stat','69% highly concerned'),(71719,1864,'_problem_icons_1_prob_concerned_stat','field_640fa0dd81d95'),(71720,1864,'problem_icons_1_prob_concerded_text','are highly concerned'),(71721,1864,'_problem_icons_1_prob_concerded_text','field_640fa10181d96'),(71722,1864,'problem_icons_1_prob_issue_text',''),(71723,1864,'_problem_icons_1_prob_issue_text','field_640fa11a81d97'),(71724,1864,'problem_icons_2_prob_icon','1699'),(71725,1864,'_problem_icons_2_prob_icon','field_640fa0291d519'),(71726,1864,'problem_icons_2_prob_concerned_stat','64% highly concerned'),(71727,1864,'_problem_icons_2_prob_concerned_stat','field_640fa0dd81d95'),(71728,1864,'problem_icons_2_prob_concerded_text','are highly concerned'),(71729,1864,'_problem_icons_2_prob_concerded_text','field_640fa10181d96'),(71730,1864,'problem_icons_2_prob_issue_text',''),(71731,1864,'