:{i:0;s:4:\"1997\";i:1;s:4:\"2067\";i:2;s:4:\"2089\";}'),(131606,2244,'_report_questions','field_6109ed5e02e5a'),(131607,2244,'intro_text','The Disability Dialogue is a place where people with disabilities, their families, organisations providing support, academics, and the wider community come together to work on things that matter to us.\r\n\r\nThe Dialogue is a hub of knowledge and collaboration, separate from government, where we work together to come up. With new ideas on important topics. Our ideas can make a big difference in how services and systems are set up for people with disabilities.'),(131608,2244,'_intro_text','field_66441acfe963c'),(131609,2244,'word_link','#'),(131610,2244,'_word_link','field_6646c69723804'),(131611,2244,'pdf_link','#'),(131612,2244,'_pdf_link','field_6646c6da23805'),(131613,2244,'intro_boxes_0_box_image','2241'),(131614,2244,'_intro_boxes_0_box_image','field_65262db5d36ee'),(131615,2244,'intro_boxes_1_box_image','2179'),(131616,2244,'_intro_boxes_1_box_image','field_65262db5d36ee'),(131617,2244,'intro_boxes_2_box_image','2012'),(131618,2244,'_intro_boxes_2_box_image','field_65262db5d36ee'),(131621,2246,'footnotes',''),(131623,6,'intro_boxes_0_box_excerpt','Excerpt text here just a sentance or so and no more.'),(131624,6,'_intro_boxes_0_box_excerpt','field_665975273e827'),(131625,6,'intro_boxes_1_box_excerpt','Excerpt text here just a sentance or so and no more.'),(131626,6,'_intro_boxes_1_box_excerpt','field_665975273e827'),(131627,6,'intro_boxes_2_box_excerpt','Excerpt text here just a sentance or so and no more.'),(131628,6,'_intro_boxes_2_box_excerpt','field_665975273e827'),(131629,2246,'banner_head',''),(131630,2246,'_banner_head','field_5b568121a8ffe'),(131631,2246,'banner_sub',''),(131632,2246,'_banner_sub','field_5b568139fd366'),(131633,2246,'banner_button','<a class=\"btn btn-home\" style=\"width: 200px;\" href=\"#project\">Sign the petition</a>'),(131634,2246,'_banner_button','field_5b568147fd367'),(131635,2246,'support_s